const webhookData = $input.first();
const body = webhookData.json.body || {};

// Ambil data dari Kirimi
const userMessage = body.message || "";
const messageType = body.messageType || "";
const userNumber = body.from || "unknown";  // ← TIDAK strip @lid, passthrough as-is
const _isLid    = String(userNumber).toLowerCase().includes('@lid');
const userLid   = String(body.originLid || (_isLid ? userNumber : '')).replace(/\D/g, '');// kunci cocok
const userPhone = _isLid ? '' : String(userNumber).replace(/\D/g, '');// utk kolom No WA
const userName = body.name || body.pushName || body.notifyName || "User";
const isFromMe = body.isFromMe === true;
const eventType = body.event || "";

// Filter: hanya pesan teks yang tidak kosong
if (messageType !== "text" || !userMessage || userMessage.trim() === "") {
    console.log('⛔ STOP: Bukan pesan teks valid');
    return [];
}

console.log('✅ LANJUT: Pesan teks valid dari user');
console.log('📱 No WA:', userNumber);

// Counter sederhana
let counter = $vars.chatCounter || 0;
counter++;
$vars.chatCounter = counter;

// Format tanggal & jam WIB
const now = new Date();
const formattedDate = now.toLocaleDateString('en-GB', {
    timeZone: 'Asia/Jakarta',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
});
const formattedTime = now.toLocaleTimeString('id-ID', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZone: 'Asia/Jakarta'
}).replace(/\./g, ':');

const processStartTs = Date.now();

const aiInputText = `[SYSTEM_DATA]
CHAT_COUNTER: ${counter}
USER_NAME: ${userName}
USER_MESSAGE: "${userMessage}"

[USER QUERY]
${userMessage}`;

return [{
    json: {
        chat_counter: counter,
        user_wa: userNumber,
        user_lid: userLid,
        user_phone: userPhone,
        user_name: userName,
        formatted_date: formattedDate,
        formatted_time: formattedTime,
        ai_input_text: aiInputText,
        original_message: userMessage,
        body: body,
        message_type: messageType,
        process_start_ts: processStartTs
    }
}];

// ====================================================================
// PROCESS COUNTER & MERGE DATA (V4)
// Fix: (1) matching row No WA primer / lid backup (bukan lid-only),
//      (2) "Tanggal Chat Pertama" dibaca dari kolom yang benar
//          (dulu baca existingRow.Tanggal yang tidak ada -> tanggal
//          pertama ter-reset jadi hari ini setiap pesan),
//      (3) error -> stop (return []) alih-alih menulis row "ERROR".
// ====================================================================
const debugLog = [];

try {
    const allItems = $input.all();
    debugLog.push("Step 1: Received " + allItems.length + " items from Read STATS");

    const chatCounter = $('Chat Counter').first().json;
    const resolve = $('Resolve User Row').first().json;
    const resolvedKey = resolve.resolved_key;

    const userName = chatCounter.user_name || "User";
    const userMessage = chatCounter.original_message || "";
    const digits = v => String(v ?? '').replace(/\D/g, '');
    const phone = digits(chatCounter.user_phone);
    const lid = digits(chatCounter.user_lid);

    if (!resolvedKey) {
        console.warn("resolved_key kosong - skip update STATS");
        return [];
    }

    // Process sheet rows
    const sheetRows = allItems
        .filter(item => {
            const data = item?.json || item;
            if (!data || Object.keys(data).length === 0) return false;
            return !!(data['lid'] || data['No WA'] || data.no_wa || data.NoWA);
        })
        .map(item => item?.json || item);

    debugLog.push("Step 2: Sheet rows found: " + sheetRows.length);

    // Find existing row: No WA primer, lid backup (konsisten dgn Resolve User Row)
    let existingRow = null;
    if (phone) existingRow = sheetRows.find(r => digits(r['No WA']) === phone) || null;
    if (!existingRow && lid) {
        existingRow = sheetRows.find(r => digits(r['lid']) === lid)
                   || sheetRows.find(r => digits(r['No WA']) === lid)
                   || null;
    }

    const isNewUser = !existingRow;
    debugLog.push("Step 3: " + (isNewUser ? "NEW USER" : "EXISTING USER"));

    let counter, pesanPertama, tanggalPertama, intensitasChat;

    if (existingRow) {
        counter = parseInt(existingRow.Counter || existingRow.counter || 0) + 1;
        intensitasChat = parseInt(existingRow['Intensitas Chat'] || existingRow.intensitas_chat || 0) + 1;

        const pesanLama = existingRow['Pesan Pertama'] || existingRow.pesan_pertama;
        pesanPertama = (pesanLama && String(pesanLama).trim() !== '') ? pesanLama : userMessage;

        // V4 FIX: baca kolom yang benar
        const tglLama = existingRow['Tanggal Chat Pertama'];
        tanggalPertama = (tglLama && String(tglLama).trim() !== '') ? tglLama : null;
    } else {
        counter = 1;
        intensitasChat = 1;
        pesanPertama = userMessage;
        tanggalPertama = null;
    }

    if (!tanggalPertama) {
        tanggalPertama = new Date().toLocaleDateString('en-GB', {
            timeZone: 'Asia/Jakarta', day: '2-digit', month: '2-digit', year: 'numeric'
        });
    }

    const outputData = {
        "No WA": resolvedKey,
        "lid": lid,
        "Tanggal": tanggalPertama,
        "TanggalSekarang": new Date().toLocaleDateString('en-GB', {
            timeZone: 'Asia/Jakarta', day: '2-digit', month: '2-digit', year: 'numeric'
        }),
        "Nama": userName,
        "Pesan Pertama": pesanPertama,
        "Counter": counter,
        "Intensitas Chat": intensitasChat
    };

    return [{ json: outputData }];

} catch (error) {
    // V4 FIX: jangan menulis row "ERROR" ke sheet - cukup log & stop.
    console.error("Process Counter ERROR: " + error.message, debugLog);
    return [];
}

const chatCounter = $('Chat Counter').first().json;

// DATA LANGSUNG DARI CHAT COUNTER NODE
const userNumber = chatCounter.user_wa;
const userName = chatCounter.user_name;
const userMessage = chatCounter.original_message;   // ← perbaikan utama

// VALIDASI SEDERHANA
if (!userNumber) {
  throw new Error("user_wa tidak ditemukan di input!");
}

console.log("✅ Data berhasil di-extract:");
console.log("- No WA:", userNumber);
console.log("- Nama:", userName);
console.log("- Pesan:", userMessage);

return [{
  json: {
    search_no_wa: userNumber,
    user_name: userName,
    user_message: userMessage,
    timestamp: chatCounter.formatted_date + ' ' + chatCounter.formatted_time + ' WIB',
    source: "chat_counter_node",
    is_valid: userNumber !== "unknown"
  }
}];

// Cek apakah Kirimi API sukses
const input = $input.first();
const responseData = input.json;

// Kirimi API return success jika ada field 'status' = true atau 'data'
const isSuccess = responseData.status === true || 
                  responseData.success === true ||
                  (responseData.data && responseData.data.id) ||
                  (responseData.message && responseData.message !== 'error');

if (!isSuccess) {
  console.log('❌ Kirimi API Response Error:', JSON.stringify(responseData));
  throw new Error('Kirimi API gagal: ' + JSON.stringify(responseData));
}

console.log('✅ Kirimi API sukses:', JSON.stringify(responseData));
return [input];

// ============================================================
// HUMAN-IN-THE-LOOP CHECK (V4: No WA primer, lid backup)
// bot_mode = 'OFF' -> Sam handle manual -> stop.
// ============================================================
const cc = $('Chat Counter').first().json;
const digits = v => String(v ?? '').replace(/\D/g, '');
const phone = digits(cc.user_phone);
const lid = digits(cc.user_lid);

const statsRows = $('Read STATS for HITL').all()
  .map(r => r.json)
  .filter(r => r && Object.keys(r).length > 0);

let userRow = null;
if (phone) userRow = statsRows.find(r => digits(r['No WA']) === phone) || null;
if (!userRow && lid) {
  userRow = statsRows.find(r => digits(r['lid']) === lid)
         || statsRows.find(r => digits(r['No WA']) === lid)
         || null;
}

const botMode = userRow ? String(userRow['bot_mode'] || '').trim().toUpperCase() : '';

if (botMode === 'OFF') {
  console.log(`👨‍💼 HITL AKTIF — Sam sedang handle manual, bot berhenti.`);
  return [];
}

console.log(`🤖 Bot mode AKTIF (bot_mode="${botMode}") — lanjut.`);
return [$input.first()];

// ====================================================================
// NODE: Cek_user_status (V4)
// Peran: gate HITL post-debounce + gabung pesan MSG_BUFFER +
//        siapkan SYSTEM_DATA (intro user baru, kelas tersimpan).
// Alur status PARENT/STUDENT sudah DIHAPUS (register netral).
// ====================================================================
const cc = $('Chat Counter').first().json;
const resolve = $('Resolve User Row').first().json;
const resolvedKey = resolve.resolved_key;

// bot_mode dicek ulang SETELAH debounce (Wait 60 detik) —
// Sam bisa set OFF kapan saja selama bot menunggu.
const debounceItem = $('Re-Read STATS Debounce').first();
const debounceRow = (debounceItem && debounceItem.json) ? debounceItem.json : {};
const botModeNow = String(debounceRow['bot_mode'] || '').trim().toUpperCase();
if (botModeNow === 'OFF') {
  console.log('👨‍💼 HITL (post-debounce): bot_mode OFF — berhenti, Sam handle manual.');
  return [];
}

// ── Gabung pesan dari MSG_BUFFER (append-only, anti lost-update) ──
// Konsumsi: ts > buffer_done_ts (watermark) dan ts <= process_start_ts saya.
const doneTs = Number(debounceRow['buffer_done_ts'] || 0) || 0;
const myTs = Number(cc.process_start_ts) || 0;
let bufRows = [];
try {
  bufRows = $('Read MSG_BUFFER').all()
    .map(i => i.json)
    .filter(r => r && r.message !== undefined && r.message !== null);
} catch (e) {
  console.warn('⚠️ Read MSG_BUFFER tidak terbaca:', e.message);
}
// Batas kedaluwarsa: pesan lebih tua dari 30 menit tidak ikut digabung
// (mis. pesan yang sempat ter-buffer lalu ditangani manual oleh Sam saat bot OFF).
const MAX_AGE_MS = 30 * 60 * 1000;
const msgs = bufRows
  .map(r => ({ ts: Number(r.ts) || 0, message: String(r.message ?? '').trim() }))
  .filter(r => r.ts > doneTs && r.ts <= myTs && (myTs - r.ts) < MAX_AGE_MS && r.message !== '')
  .sort((a, b) => a.ts - b.ts)
  .map(r => r.message);

// Fallback aman: kalau buffer kosong (mis. append gagal), pakai pesan asli.
const userMessage = msgs.length ? msgs.join('\n') : (cc.original_message || '');
console.log(`📨 userMessage final ke AI (${msgs.length} pesan digabung):\n${userMessage}`);

// ── User baru? (greeting_sent belum Y) ──
const greetingSent = String(debounceRow['greeting_sent'] || resolve.greeting_sent || '').trim().toUpperCase();
const isNewUser = greetingSent !== 'Y';

// ── Fakta persisten (tahan restart n8n / reset memory) ──
// TTL 60 hari: kelas berubah tiap tahun ajaran, jangan injeksi data basi.
const KELAS_TTL_S = 60 * 86400;
const kelasTs = Number(debounceRow['kelas_anak_ts'] || resolve.kelas_anak_ts || 0) || 0;
const kelasFresh = kelasTs > 0 && (Math.floor(Date.now() / 1000) - kelasTs) <= KELAS_TTL_S;
const kelasAnak = kelasFresh ? String(debounceRow['kelas_anak'] || resolve.kelas_anak || '').trim() : '';
const programInterest = kelasFresh ? String(debounceRow['program_interest'] || resolve.program_interest || '').trim() : '';
if (kelasTs && !kelasFresh) console.log('⏳ kelas_anak kedaluwarsa (>60 hari) — tidak diinjeksi.');

const INTRO = 'Haloo thank you sudah contact TheScholars.id yaa. Saya Sam versi AI yaa, saya siap bantu untuk jawab pertanyaan yang ada mengenai program kita dan scholarships ke Singapore.';

const aiSystemData = `[SYSTEM_DATA]
USER_WA: ${resolvedKey}
IS_NEW_USER: ${isNewUser}
KELAS_ANAK: ${kelasAnak || 'UNKNOWN'}
PROGRAM_INTEREST: ${programInterest || 'UNKNOWN'}

CRITICAL INSTRUCTION:
${isNewUser
  ? `USER BARU. Baris pertama balasan WAJIB intro ini PERSIS (jangan diubah/diringkas): "${INTRO}" Setelah intro, di pesan yang sama langsung jawab pertanyaan user kalau ada. Kalau user hanya menyapa, cukup intro saja.`
  : 'User lama. JANGAN kirim intro/perkenalan lagi, lanjutkan percakapan secara natural. Jangan reset percakapan dari awal.'}

[USER QUERY]
${userMessage}`;

return [{
  json: {
    ...cc,
    resolved_key: resolvedKey,
    ai_input_text: aiSystemData,
    user_message_final: userMessage,
    is_new_user: isNewUser,
    kelas_anak_db: kelasAnak,
    program_interest_db: programInterest,
    buffer_done_ts_old: doneTs
  }
}];

// ====================================================================
// UPDATE GREETING FLAG (V4 - disederhanakan)
// Dulu: pattern-matching teks balasan (rapuh, tergantung susunan
// kalimat). Sekarang: cukup dari flag is_new_user — kalau eksekusi
// ini mengirim intro ke user baru (reply sudah SUKSES terkirim
// karena node ini jalan setelah Reply Chat Kirimi), tandai Y.
// ====================================================================
const isNewUser = $('Cek_user_status').first().json.is_new_user === true;

if (isNewUser) {
  console.log('📝 [GREETING] intro terkirim ke user baru -> greeting_sent = Y');
}

return [{
  json: {
    update_needed: isNewUser ? 'true' : 'false',
    greeting_sent: 'Y'
  }
}];

// ============================================
// PREPROCESS - CONTEXT DETECTION (V4)
// - Deteksi status PARENT/STUDENT DIHAPUS (register netral).
// - Deteksi kelas MULTI-VALUE: bisa menangkap >1 kelas dalam satu
//   pesan (kasus orang tua dengan beberapa anak). Disimpan sebagai
//   daftar "SMP 1, SD 6".
// - Dukung jenjang Singapura/internasional (Primary/Sec) & angka
//   Romawi; fallback kelas tersimpan dari DB (kelas_anak, TTL di
//   Cek_user_status).
// ============================================

const json = $input.item.json;

// Get the full message (includes SYSTEM_DATA + user query)
const fullMessage = json.message || json.ai_input_text || json.text || json.body || '';

// ============================================
// 1. EXTRACT USER QUERY
// ============================================
let actualUserMessage = '';
if (fullMessage.includes('[USER QUERY]')) {
  const parts = fullMessage.split('[USER QUERY]');
  actualUserMessage = parts[1] ? parts[1].trim() : '';
} else {
  actualUserMessage = fullMessage.trim();
}

// ============================================
// 2. PARSE SYSTEM_DATA
// ============================================
let isNewUser = false;
let kelasAnakDB = '';
let programInterestDB = '';

if (fullMessage.includes('[SYSTEM_DATA]')) {
  const newUserMatch = fullMessage.match(/IS_NEW_USER:\s*(\w+)/i);
  if (newUserMatch) isNewUser = newUserMatch[1].toLowerCase() === 'true';

  const kelasMatch = fullMessage.match(/KELAS_ANAK:\s*([^\n]+)/i);
  if (kelasMatch) {
    const v = kelasMatch[1].trim();
    if (v && v.toUpperCase() !== 'UNKNOWN') kelasAnakDB = v;
  }
  const progMatch = fullMessage.match(/PROGRAM_INTEREST:\s*([^\n]+)/i);
  if (progMatch) {
    const v = progMatch[1].trim();
    if (v && v.toUpperCase() !== 'UNKNOWN') programInterestDB = v;
  }
}

// ============================================
// 3. PROCESS MESSAGE
// ============================================
const message = actualUserMessage.toLowerCase();
const userPhone = json.userPhone || json.from || json.phone || json.user_wa || 'unknown';

// ============================================
// 4. DETECT GRADE(S) & PROGRAM(S) — MULTI-VALUE
//    Semua pola discan (bukan berhenti di match pertama) supaya
//    ">1 anak" dalam satu pesan tertangkap semua.
//    Seniors KHUSUS kelas 12. SMA 10/11 -> belum ada program.
// ============================================
const GRADE_PATTERNS = [
  // Jenjang internasional/Singapura (intl=true)
  [/\b(?:primary|pri)\s*\.?\s*6\b|\bp6\b/i,        'SD 6',      'Junior',       true],
  [/\b(?:sec|secondary)\s*\.?\s*1\b/i,             'SMP 1',     'Junior',       true],
  [/\b(?:sec|secondary)\s*\.?\s*2\b/i,             'SMP 2',     'Intermediate', true],
  [/\b(?:sec|secondary)\s*\.?\s*3\b/i,             'SMP 3',     'Intermediate', true],
  [/\b(?:sec|secondary)\s*\.?\s*4\b/i,             'SMA 10/11', '',             true],
  // Angka Romawi (\b menjaga 'kelas x' tidak match di 'kelas xii')
  [/kelas\s*xii\b/i,                               'SMA 12',    'Seniors',      false],
  [/kelas\s*xi\b/i,                                'SMA 10/11', '',             false],
  [/kelas\s*x\b/i,                                 'SMA 10/11', '',             false],
  // Pola Indonesia
  [/sd 6|kelas 6 sd|kelas 6(?!\s*smp)/i,           'SD 6',      'Junior',       false],
  [/smp 1|kelas 1 smp|kelas 7\b/i,                 'SMP 1',     'Junior',       false],
  [/smp 2|kelas 2 smp|kelas 8\b/i,                 'SMP 2',     'Intermediate', false],
  [/smp 3|kelas 3 smp|kelas 9\b/i,                 'SMP 3',     'Intermediate', false],
  [/sma 3|kelas 3 sma|kelas 12\b/i,                'SMA 12',    'Seniors',      false],
  [/sma 1|sma 2|kelas 1 sma|kelas 2 sma|kelas 10\b|kelas 11\b/i, 'SMA 10/11', '', false],
];

const PROGRAM_OF = { 'SD 6': 'Junior', 'SMP 1': 'Junior', 'SMP 2': 'Intermediate', 'SMP 3': 'Intermediate', 'SMA 12': 'Seniors', 'SMA 10/11': '' };

let grades = [];
let intlSystemDetected = false;
for (const [re, label, prog, intl] of GRADE_PATTERNS) {
  if (re.test(message) && !grades.includes(label)) {
    grades.push(label);
    if (intl) intlSystemDetected = true;
  }
}
// Fallback generik SMA (kelas belum jelas) hanya kalau tidak ada match lain
let smaUnclear = false;
if (!grades.length && message.match(/sma|kelas.*sma/i)) {
  smaUnclear = true;
}

// Fallback: kelas tersimpan dari percakapan sebelumnya (DB, sudah lolos TTL)
let gradeFromDB = false;
if (!grades.length && !smaUnclear && kelasAnakDB) {
  grades = kelasAnakDB.split(',').map(s => s.trim()).filter(Boolean);
  gradeFromDB = true;
}

const programs = [...new Set(grades.map(g => PROGRAM_OF[g] || '').filter(Boolean))];
const noProgramGrades = grades.filter(g => !(PROGRAM_OF[g] || ''));

// String gabungan (dipakai untuk penyimpanan kelas_anak & kompatibilitas)
const grade = grades.join(', ');
const recommendedProgram = gradeFromDB && programInterestDB ? programInterestDB : programs.join(', ');

// ============================================
// 5. DETECT REGISTRATION INTENT
// ============================================
const wantsToRegister = message.match(/daftar|mau ikut|tertarik|mau coba|mau daftar|link pendaftaran|link form|minta link/i) !== null;

// ============================================
// 5b. DETECT OUT-OF-SCOPE USER (di luar jenjang SMP-SMA)
// ============================================
let outOfScope = false;
if (message.match(/\b(mahasiswa|semester\s*\d+|lagi kuliah|sudah kuliah|udah kuliah|sarjana|magister|fresh graduate|gap year|karyawan|pegawai|sudah lulus|udah lulus|sudah kerja|udah kerja)\b/i)) {
  outOfScope = true;
}

// ============================================
// 5c. DETECT UNCLEAR / AMBIGUOUS SHORT REPLY (anti-loop)
// ============================================
const isGreetingLike = message.match(/^(hai|halo|hi|pagi|siang|sore|malam|makasih|thanks|terima kasih|ok|oke|sip|baik|👍|🙏)/i) !== null;
const unclearReply = (actualUserMessage.trim().length <= 4) && !grades.length && !isGreetingLike && !wantsToRegister;

// ============================================
// 6. DETECT PERSUASION TRIGGERS
// ============================================
let persuasionMode = '';
if (message.match(/mau daftar|tertarik|boleh deh|mau coba|mau ikut|oke deh/i)) {
  persuasionMode = 'INTERESTED';
} else if (message.match(/nanti|pikir dulu|setelah ujian|belum sekarang|ragu|mikir|lihat dulu/i)) {
  persuasionMode = 'DEFER';
} else if (message.match(/\b(tf|transfer|bayar|mau bayar|sudah bayar|kirim bukti)\b/i)) {
  persuasionMode = 'PAYMENT';
}

// ============================================
// 7. DETECT TOPICS
// ============================================
const discussingProgram = message.match(/program|junior|intermediate|senior|batch/i) !== null;
const askingPrice = message.match(/berapa|biaya|harga|bayar|mahal|murah/i) !== null;
const askingBatch = message.match(/batch|kapan|mulai|jadwal|pendaftaran/i) !== null;

// ============================================
// 8. BUILD AI CONTEXT
//    HANYA fakta deteksi + pointer, selaras system message.
// ============================================
let aiContext = '';

if (outOfScope) {
  aiContext += `User kemungkinan di luar jenjang SMP-SMA (mahasiswa/kuliah/kerja). Sampaikan jujur program khusus siswa SMP-SMA, jadi belum ada yang cocok. JANGAN tanya kelas SMP/SMA. `;
}

if (unclearReply) {
  aiContext += `Balasan user terlalu singkat/ambigu. JANGAN ulang pertanyaan yang sama. Kalau sebelumnya sudah bertanya hal yang sama, tawarkan bantuan langsung dari Sam: [TALK_TO_SAM]. `;
}

if (intlSystemDetected) {
  aiContext += `User menyebut jenjang sistem Singapura/internasional (Primary/Sec). Ini TIDAK berarti calon murid sudah bersekolah di Singapura, banyak sekolah kurikulum internasional di Indonesia. Jangan asumsikan lokasi sekolah, dan JANGAN tanya lokasi kecuali menentukan jawaban. `;
}

if (!outOfScope && grades.length) {
  const src = gradeFromDB ? 'SUDAH DIKETAHUI dari percakapan sebelumnya' : 'disebut di pesan ini';
  if (grades.length === 1) {
    const g = grades[0];
    const p = PROGRAM_OF[g] || '';
    if (p) {
      aiContext += `Kelas calon murid ${src}: ${g} -> arahkan ke program ${p}. ${gradeFromDB ? 'JANGAN tanya kelas lagi. ' : ''}Catatan: SMP 2 = Intermediate (BUKAN Junior). Sebut HANYA program ${p}, jangan tawarkan tier program lain kecuali user tanya. `;
    } else if (g === 'SMA 10/11') {
      aiContext += `Calon murid di SMA kelas 10/11 -> belum ada program yang cocok untuk sekarang (Seniors khusus kelas 12). Sampaikan jujur dan arahkan ke opsi yang ada.${gradeFromDB ? ' Kelas sudah diketahui, JANGAN tanya kelas lagi.' : ''} `;
    }
  } else {
    // Multi-anak: sebutkan pemetaan per kelas
    const mapText = grades.map(g => `${g} -> ${PROGRAM_OF[g] || 'belum ada program yang cocok (Seniors khusus kelas 12)'}`).join('; ');
    aiContext += `User menyebut LEBIH DARI SATU kelas calon murid (kemungkinan beberapa anak), ${src}: ${mapText}. JANGAN tanya ulang kelas. Bahas program sesuai kelas masing-masing, ringkas, tanpa membandingkan tier lain di luar itu. Catatan: SMP 2 = Intermediate (BUKAN Junior). `;
  }
} else if (smaUnclear) {
  aiContext += `Calon murid SMA tapi kelas belum jelas -> tanya dulu kelas berapa (Seniors hanya untuk kelas 12). `;
}

if (wantsToRegister) {
